//! zom-sql infer: Zig schema source from a database catalog.
//!
//! A Zig schema can't be read from the database at compile time, so this
//! generates one ahead of time instead. A driver (zom-pg's `introspect`)
//! fills a `Catalog` from the database, and `render` turns it into a file
//! of tuple structs, `zom.Schema` declarations and enums:
//!
//!     // generated by zom-sql infer from schema "public"; do not edit
//!
//!     const zom = @import("zom");
//!
//!     pub const Users = struct {
//!         id: i32,
//!         name: []const u8,
//!         deleted_at: ?i64 = null,
//!     };
//!     pub const UsersSchema = zom.Schema(Users, "users", .id, .{});
//!
//! Nothing here knows SQL type names: the driver maps each column to a
//! `Type`, or to null for a type its gateway can't decode, which `render`
//! leaves out with a comment.

const std = @import("std");
const Allocator = std.mem.Allocator;
const Writer = std.Io.Writer;

/// The Zig type of a column's field.
pub const Type = union(enum) {
    int: std.builtin.Type.Int,
    /// The bit count: 32 or 64.
    float: u16,
    bool,
    /// `[]const u8`.
    string,
    /// The `Catalog.enums` entry with this name.
    @"enum": []const u8,

    pub fn format(t: Type, w: *Writer) Writer.Error!void {
        switch (t) {
            .int => |i| try w.print("{c}{d}", .{ @as(u8, if (i.signedness == .signed) 'i' else 'u'), i.bits }),
            .float => |bits| try w.print("f{d}", .{bits}),
            .bool => try w.writeAll("bool"),
            .string => try w.writeAll("[]const u8"),
            .@"enum" => |name| try writeTypeName(w, name, ""),
        }
    }
};

pub const Column = struct {
    name: []const u8,
    /// Null when no Zig type fits; the field is left out, with a comment.
    type: ?Type,
    /// The database's name for the type, for that comment.
    sql_type: []const u8,
    nullable: bool,
};

pub const Table = struct {
    name: []const u8,
    /// In table order.
    columns: []const Column,
    /// Its columns, in key order; empty when the table has none.
    primary_key: []const []const u8,
};

pub const Enum = struct {
    name: []const u8,
    /// In sort order.
    labels: []const []const u8,
};

pub const Catalog = struct {
    /// The database schema the tables come from, for the header.
    schema: []const u8,
    tables: []const Table,
    enums: []const Enum = &.{},
};

pub const Options = struct {
    /// The name the generated file `@import`s zom by.
    zom_import: []const u8 = "zom",
};

pub const Error = error{
    OutOfMemory,
    /// Two declarations would get the same Zig name; see `findCollision`.
    NameCollision,
    /// A column's `.@"enum"` names no entry of `Catalog.enums`.
    UnknownEnum,
};

/// Two catalog entries whose declarations would get the same Zig name.
pub const Collision = struct {
    first: Origin,
    second: Origin,

    pub const Origin = struct {
        kind: enum { table, schema, @"enum" },
        /// The table's or enum's database name.
        name: []const u8,

        fn writeZigName(o: Origin, w: *Writer) Writer.Error!void {
            try writeTypeName(w, o.name, if (o.kind == .schema) "Schema" else "");
        }

        pub fn format(o: Origin, w: *Writer) Writer.Error!void {
            switch (o.kind) {
                .table => try w.print("table \"{f}\"", .{std.zig.fmtString(o.name)}),
                .schema => try w.print("the schema of table \"{f}\"", .{std.zig.fmtString(o.name)}),
                .@"enum" => try w.print("enum \"{f}\"", .{std.zig.fmtString(o.name)}),
            }
        }
    };

    /// `table "users_schema" and the schema of table "users" both become UsersSchema`
    pub fn format(c: Collision, w: *Writer) Writer.Error!void {
        try w.print("{f} and {f} both become ", .{ c.first, c.second });
        try c.first.writeZigName(w);
    }
};

/// The first pair of declarations that would get the same Zig name, or
/// null. `render` fails with `error.NameCollision` when there is one.
pub fn findCollision(gpa: Allocator, catalog: Catalog) Allocator.Error!?Collision {
    var arena: std.heap.ArenaAllocator = .init(gpa);
    defer arena.deinit();
    const a = arena.allocator();

    var seen: std.StringHashMapUnmanaged(Collision.Origin) = .empty;
    for (catalog.enums) |e| {
        if (try claim(a, &seen, .{ .kind = .@"enum", .name = e.name })) |c| return c;
    }
    for (catalog.tables) |t| {
        if (try claim(a, &seen, .{ .kind = .table, .name = t.name })) |c| return c;
        if (schemaBlocker(t) == null) {
            if (try claim(a, &seen, .{ .kind = .schema, .name = t.name })) |c| return c;
        }
    }
    return null;
}

fn claim(a: Allocator, seen: *std.StringHashMapUnmanaged(Collision.Origin), origin: Collision.Origin) Allocator.Error!?Collision {
    var name: Writer.Allocating = .init(a);
    origin.writeZigName(&name.writer) catch return error.OutOfMemory;
    const gop = try seen.getOrPut(a, name.written());
    if (gop.found_existing) return .{ .first = gop.value_ptr.*, .second = origin };
    gop.value_ptr.* = origin;
    return null;
}

/// The generated file, formatted as `zig fmt` would. The caller owns it.
pub fn render(gpa: Allocator, catalog: Catalog, options: Options) Error![]u8 {
    if (try findCollision(gpa, catalog) != null) return error.NameCollision;
    for (catalog.tables) |t| for (t.columns) |c| {
        const ty = c.type orelse continue;
        if (ty == .@"enum" and findEnum(catalog, ty.@"enum") == null) return error.UnknownEnum;
    };

    var out: Writer.Allocating = .init(gpa);
    defer out.deinit();
    writeSource(&out.writer, catalog, options) catch return error.OutOfMemory;
    out.writer.writeByte(0) catch return error.OutOfMemory;
    const source = out.written();

    var tree = try std.zig.Ast.parse(gpa, source[0 .. source.len - 1 :0], .zig);
    defer tree.deinit(gpa);
    // A parse error here is a bug in `writeSource`, not in the catalog.
    if (tree.errors.len != 0) {
        var buf: [256]u8 = undefined;
        var w = std.Io.Writer.fixed(&buf);
        tree.renderError(tree.errors[0], &w) catch {};
        std.debug.panic("zom-sql infer generated invalid Zig: {s}\n{s}", .{ w.buffered(), source });
    }
    return tree.renderAlloc(gpa);
}

fn writeSource(w: *Writer, catalog: Catalog, options: Options) Writer.Error!void {
    try w.print("// generated by zom-sql infer from schema \"{f}\"; do not edit\n\n", .{std.zig.fmtString(catalog.schema)});
    try w.print("const {f} = @import(\"{f}\");\n", .{ std.zig.fmtId(options.zom_import), std.zig.fmtString(options.zom_import) });

    for (catalog.enums) |e| {
        try w.writeAll("\npub const ");
        try writeTypeName(w, e.name, "");
        try w.writeAll(" = enum {\n");
        for (e.labels) |label| try w.print("{f},\n", .{std.zig.fmtIdP(label)});
        try w.writeAll("};\n");
    }

    for (catalog.tables) |t| {
        try w.writeAll("\npub const ");
        try writeTypeName(w, t.name, "");
        try w.writeAll(" = struct {\n");
        for (t.columns) |c| {
            const ty = c.type orelse {
                try w.print("// skipped {f}: no Zig type for {f}\n", .{ std.zig.fmtIdP(c.name), std.zig.fmtString(c.sql_type) });
                continue;
            };
            try w.print("{f}: ", .{std.zig.fmtIdP(c.name)});
            if (c.nullable) {
                try w.print("?{f} = null,\n", .{ty});
            } else {
                try w.print("{f},\n", .{ty});
            }
        }
        try w.writeAll("};\n");

        if (schemaBlocker(t)) |why| {
            try w.writeAll("// no ");
            try writeTypeName(w, t.name, "Schema");
            try w.writeAll(": ");
            switch (why) {
                .no_primary_key => try w.writeAll("the table has no primary key"),
                .composite => {
                    try w.writeAll("zom needs a single-column primary key, the table's is (");
                    for (t.primary_key, 0..) |k, i| {
                        if (i != 0) try w.writeAll(", ");
                        try w.print("{f}", .{std.zig.fmtIdP(k)});
                    }
                    try w.writeAll(")");
                },
                .skipped => try w.print("its primary key {f} was skipped", .{std.zig.fmtIdP(t.primary_key[0])}),
            }
            try w.writeAll("\n");
        } else {
            try w.writeAll("pub const ");
            try writeTypeName(w, t.name, "Schema");
            try w.print(" = {f}.Schema(", .{std.zig.fmtId(options.zom_import)});
            try writeTypeName(w, t.name, "");
            try w.print(", \"{f}\", .{f}, .{{}});\n", .{ std.zig.fmtString(t.name), std.zig.fmtIdP(t.primary_key[0]) });
        }
    }
}

const SchemaBlocker = enum { no_primary_key, composite, skipped };

/// Why `t` gets no `zom.Schema`, or null when it gets one.
fn schemaBlocker(t: Table) ?SchemaBlocker {
    if (t.primary_key.len == 0) return .no_primary_key;
    if (t.primary_key.len > 1) return .composite;
    for (t.columns) |c| {
        if (std.mem.eql(u8, c.name, t.primary_key[0])) return if (c.type == null) .skipped else null;
    }
    return .skipped;
}

fn findEnum(catalog: Catalog, name: []const u8) ?Enum {
    for (catalog.enums) |e| if (std.mem.eql(u8, e.name, name)) return e;
    return null;
}

/// `name` in PascalCase plus `suffix`, as a Zig identifier: `user_roles`
/// becomes `UserRoles`, and a name that still isn't a valid identifier
/// (`2fa_codes` becomes `@"2faCodes"`) is quoted.
fn writeTypeName(w: *Writer, name: []const u8, suffix: []const u8) Writer.Error!void {
    var buf: [256]u8 = undefined;
    var pascal = std.ArrayList(u8).initBuffer(&buf);
    var upper = true;
    for (name) |byte| {
        const word = std.ascii.isAlphanumeric(byte) or byte >= 0x80;
        if (!word) {
            upper = true;
            continue;
        }
        if (pascal.unusedCapacitySlice().len == 0) break;
        pascal.appendAssumeCapacity(if (upper) std.ascii.toUpper(byte) else byte);
        upper = false;
    }
    // Long or all-punctuation names are kept as they are, quoted.
    const base = if (pascal.items.len == 0 or pascal.items.len == buf.len) name else pascal.items;
    if (suffix.len == 0) return w.print("{f}", .{std.zig.fmtId(base)});

    var joined: [buf.len + 16]u8 = undefined;
    if (base.len + suffix.len > joined.len) {
        // Too long to join on the stack; quote it in pieces instead.
        try w.print("@\"{f}{s}\"", .{ std.zig.fmtString(base), suffix });
        return;
    }
    @memcpy(joined[0..base.len], base);
    @memcpy(joined[base.len..][0..suffix.len], suffix);
    try w.print("{f}", .{std.zig.fmtId(joined[0 .. base.len + suffix.len])});
}
